// ---------- Notable historical events ----------
// People whose lives touch an event outside the family's own story. Attached by id;
// drawn as a ring on the node and a callout on the card. Text follows RESEARCH.md.
const EVENTS = {
  jacques:{ tag:"Revocation of the Edict of Nantes, 1685", text:"A dyer and a deacon of the Reformed church of Metz, he was buried on October 8, 1685, days before the Edict of Fontainebleau outlawed Protestant worship in France and scattered his family into the Huguenot diaspora." },
  louis:{ tag:"Revocation of the Edict of Nantes, 1685", text:"He was nine when the Revocation closed the Metz temple. Because no Protestant marriage could be solemnized in French Metz, he crossed to Zweibrücken to wed in 1697; in 1715, a widower, he declared his five surviving children Protestant before the Metz authorities." },
  paul1617:{ tag:"Emigration to Norway, 1644", text:"He and his brother Jacques left Metz for Norway in 1644, in the years when Huguenot families were scattering out of Lorraine, and he took a commission there the same year — lieutenant in 1644, major by 1658. The two brothers are the origin of the Norwegian Michelets, an army family that produced officers and generals into the nineteenth century." },
  jacques1619:{ tag:"Emigration to Norway, 1644", text:"He left Metz for Norway with his elder brother Paul in 1644. Between them they founded the Norwegian branch of the family; the Berlin table records nothing further of him." },
  suzannemangeot:{ tag:"Revocation of the Edict of Nantes, 1685", text:"The Revocation is why she was married where she was. No Protestant marriage could be solemnised in French Metz after 1685, so she and Louis crossed to Zweibrücken in 1697 to wed, and her diary records that they stayed there until their first son was born and baptised. In 1699 the couple declared openly for the Reformed faith at Metz as nouveaux convertis." },
  jj1:{ tag:"Landing at Philadelphia, 1733", text:"Sailed from Rotterdam on the Hope of London, Daniel Reid master, by way of Cowes, and landed at Philadelphia on August 28, 1733, one of 389 Palatine passengers. The list spells him Johan Jacob Mückli; he took the oath of allegiance the same week." },
  ulrich:{ tag:"Landing at Philadelphia, 1733", text:"He landed at Philadelphia on September 28, 1733, with Abraham Wotring and John Nicholas Saeger, bringing a wife and six children out of Switzerland. John Jacob Mickley had come ashore at the same port a month earlier, on August 28. The two men did not know it, but their families were already converging: Burkhalter\u2019s daughter Elizabeth Barbara, fourteen that year, would marry Mickley, and every Mickley in this tree descends from the pair of crossings." },
  elizbarbara:{ tag:"Landing at Philadelphia, 1733", text:"She was fourteen, one of the six children Ulrich Burkhalter brought ashore at Philadelphia on September 28, 1733. Her future husband had landed a month before her. Their children were the first generation of the family born in America." },
  peterburk:{ tag:"Pennsylvania Constitutional Convention, 1776", text:"Elected on July 8, 1776, four days after the Declaration, to the convention that met in Philadelphia on the 15th to write Pennsylvania\u2019s first constitution \u2014 the most radically democratic of the new state constitutions, with no governor and a single house. He was elected that November to the first Assembly under it and returned five times more. He had already been captain of a company of associators since May 22, 1775." },
  josephbiery:{ tag:"Landing at Philadelphia, 1739", text:"He landed from the ship Samuel, Hugh Percy master, and took the oath of allegiance at the Colonial Court House on August 27, 1739. Among his fellow passengers were the eight Doll brothers and sisters; he married one of them, Elizabeth, soon after." },
  elizabethdoll:{ tag:"Landing at Philadelphia, 1739", text:"She crossed on the Samuel in 1739 with her four brothers and three sisters, and married her fellow passenger Joseph Biery soon after landing." },
  michaelnewhard:{ tag:"Landing at Philadelphia, 1737", text:"He sailed from Rotterdam on the St. Andrew with his brothers George Frederick and George, and landed at Philadelphia on September 26, 1737, swearing allegiance the same day before James Logan and his fellow judges. George Kern, whose granddaughter would marry into the Mickleys, was on the same ship." },
  georgekern:{ tag:"Landing at Philadelphia, 1737", text:"He landed at Philadelphia on September 26, 1737, with his wife Catharine Elizabeth and his eldest son George Jacob, on the same ship as the three Newhard brothers; family tradition held that a child was born on the voyage." },
  christianmiller:{ tag:"French and Indian War, 1755–1758", text:"The raids that emptied the Lehigh frontier after Braddock’s defeat drove him off his Lynn Township warrants and back into Berks County. He returned when the war moved west, and added a third warrant in 1767." },
  henry1754:{ tag:"The Whitehall raid, 1763", text:"Killed on October 8, 1763, while gathering chestnuts near Mickleys with his sister Barbara, in the frontier violence that followed Pontiac's War. The same raid struck the neighboring Schneider household; his brother John Peter escaped." },
  barbara1756:{ tag:"The Whitehall raid, 1763", text:"Killed at about seven years old alongside her brother Henry on October 8, 1763, in the raid on Whitehall Township that followed Pontiac's War." },
  jj2:{ tag:"The Liberty Bell hidden from the British, 1777", text:"After Brandywine, the Executive Council ordered Philadelphia's bells out of the city so the British could not melt them into cannon — eleven bells, moved at night under the appearance of farm wagons. The State House bell rode on his wagon, drawn by his own horses, with his eleven-year-old son beside him. The Moravian diary at Bethlehem records on September 23, 1777 that the wagon broke down under the weight and had to be unloaded." },
  jj3:{ tag:"The Liberty Bell hidden from the British, 1777", text:"At eleven he rode the wagon carrying the State House bell out of Philadelphia, and was now and then allowed to drive. He told the story of that first trip to the city to his grandchildren, and it was still being repeated in the family in 1893. He later marched with the state militia to western Pennsylvania in the Whiskey Rebellion of 1794." },
  sarah1786:{ tag:"The Liberty Bell hidden from the British, 1777", text:"She married a son of Pastor Abraham Blumer, who helped hide the bell beneath the floor of Zion Reformed Church in Allentown, where it lay until June 1778." },
  johnmartin:{ tag:"Battle of Germantown, 1777", text:"A soldier of the Revolution, in the line at Germantown on October 4, 1777. In 1794 he moved to Adams County near Gettysburg and founded the family's large branch there." },
  johnpeter:{ tag:"Fifer through the Revolution", text:"Escaped the raid of October 8, 1763 that killed his brother Henry and sister Barbara, then served against the Indians and through the whole of the Revolutionary War as a fifer, Germantown included. His son Peter served in the War of 1812." },
  sgtfred:{ tag:"Berks County militia, 1780 and 1782", text:"A Colebrookdale tailor who served twice as a sergeant of the Berks County militia: in Capt. Henry Strouch's company of Col. Joseph Hiester's Sixth Battalion, on active duty from August 10 to September 9, 1780, and in Capt. Abraham Keefer's company mustered September 10, 1782." },
  williamsr:{ tag:"Founding of Chatham, 1656–1712", text:"In 1656 he bought about four square miles of Monomoit from the sachem Mattaquason for a shallop, ten coats, six kettles, twelve axes, twelve hoes, twelve knives, forty shillings in wampum, a hat, and twelve shillings in coin. He had not asked Plymouth Colony's leave, and sixteen years of dispute followed before he settled it in 1672 for ninety pounds. He held church services in his own house, and his children and grandchildren saw Monomoit incorporated as Chatham on June 11, 1712." },
  anne:{ tag:"The 1637 crossing to New England", text:"Sailed from Norwich in April 1637 with her husband, their four children, and her parents Nicholas and Bridget Busby, on either the Rose or the John and Dorothy, landing on June 20. The Nickerson Family Association puts the sailing on April 15 and the landing at Salem; Savage says they embarked on April 8 at Ipswich or Yarmouth and came ashore at Boston. Neither has been checked against a passenger list." },
  nicholasbusby:{ tag:"The 1637 crossing to New England", text:"Left Norwich at fifty with his wife Bridget and four of their children to join his daughter's family on the 1637 crossing, one of the eight in the Nickerson party aboard the Rose or the John and Dorothy. He settled at Watertown and was a freeman within the year." },
  bridgetbusby:{ tag:"The 1637 crossing to New England", text:"Crossed from Norwich in 1637 at fifty-three, with her husband Nicholas, four of their children, and her daughter Anne's family, among about a hundred passengers on the Rose or the John and Dorothy." },
  nicholasbusbyjr:{ tag:"The 1637 crossing to New England", text:"The eldest Busby son, born in England, and one of the four children who crossed with Nicholas and Bridget in 1637." },
  johnbusby:{ tag:"The 1637 crossing to New England", text:"One of the four Busby children who crossed in 1637. He had returned to England by 1657, when his father's will left him the books of physic." },
  abrahambusby:{ tag:"The 1637 crossing to New England", text:"One of the four Busby children who crossed in 1637; he settled at Boston as a linen-weaver and was of the Artillery Company by 1647." },
  sarahbusby:{ tag:"The 1637 crossing to New England", text:"The youngest Busby daughter, and one of the four children who crossed in 1637; she married into Sudbury, first to Capt. Thomas Cakebread and then to John Grout." },
  elizabethn:{ tag:"The 1637 crossing to New England", text:"One of the four Nickerson children born at Norwich who crossed in 1637. She married Robert Eldred of Yarmouth in 1649; their son Nicholas became Chatham's first representative under the new charter of 1692." },
  annn:{ tag:"The 1637 crossing to New England", text:"One of the four Nickerson children born at Norwich who crossed in 1637, named for her mother; she married Tristram Hedges of Boston in 1657." },
  zachary:{ tag:"Civil War", text:"Named for the general who had just been elected president. He served as a corporal in the Civil War and drew a pension from 1896, by which time he had settled in Mason County, Illinois." },
  edwin:{ tag:"Emergency of 1863", text:"First lieutenant of Company B, 38th Pennsylvania Volunteer Militia, raised in the emergency of 1863. When the 1864 subscription to mark the immigrant John Jacob Mickley's grave fell short, he made up the difference himself and had the couple reinterred." },
  josephj:{ tag:"Father of American numismatics", text:"He assembled the finest coin collection in America of its day and was first president of the Numismatic and Antiquarian Society of Philadelphia, founded 1857. A burglary on April 13, 1867 led him to sell most of the coins at auction that autumn; from 1869 to 1872 he toured the mints of Europe gathering specimens for the United States Mint." },
  karl:{ tag:"Editor of Hegel's collected works", text:"A pupil of Hegel and professor at Berlin from 1829, he edited Hegel's collected works between 1832 and 1842 and founded the Berlin Philosophical Society in 1845. In 1883 he answered a letter from Minnie Mickley with the Michelet family table reaching back to 1444 — the document much of this tree still rests on." },
  adolphmartin:{ tag:"Immigrant, 1881", text:"Came from Baden-Württemberg to the United States in 1881, married Catharine Herring in Schuylkill County in 1887, and kept house at Grier City in Rush Township." },
  martinc:{ tag:"Immigrant, 1885", text:"Came from Denmark to the United States in 1885 and married Inger Mathilde Olsen in a Lutheran church in Chicago on November 7, 1891." },
  ingasr:{ tag:"Emigrant from Egersund", text:"Born on Christmas Day 1868 in Egersund, a fishing and pottery town on Norway's southwest coast, she emigrated to Chicago and married Martin Christoffersen there on November 7, 1891." },
  georgebaran:{ tag:"Immigrant, 1889", text:"Came in 1889 from the Slovak north of the Kingdom of Hungary, leaving his wife Mary and their first children to follow; the family was reunited in Bayonne by 1900, where seven more children were born." },
  fred1920:{ tag:"World War II: Utah Beach to the Rhine", text:"310th Field Artillery Battalion, 79th Infantry Division. He heard the news of Pearl Harbor at the Majestic Theater in Tamaqua, where his future wife was an usherette, and was drafted in October 1942. The 79th landed at Utah Beach on June 12–14, 1944: Cherbourg, the Falaise pocket, a night crossing of the Seine on a catwalk with the 313th Infantry, Belgium and Holland, Hatten-Rittershoffen in January 1945, the Rhine at Remagen, the Ruhr, Würzburg, Pilsen. He recorded his war for the Library of Congress on December 3, 2002." },
  marie:{ tag:"Pearl Harbor, December 7, 1941", text:"An usherette at the Majestic Theater in Tamaqua, managed by her aunt, she was on shift with Fred Millet the day the news of Pearl Harbor came. They married after the war and had sixty-two years together." },
  willard:{ tag:"U.S. Navy, World War II", text:"Served in the Navy in the Second World War and was honorably discharged, then built a life in New Jersey as a master carpenter, builder, and contractor." }
};

